        verify([OUTCOME.X_WIN, OUTCOME.O_WIN, OUTCOME.O_KOMI].includes(state.outcome), "Draw or unknown leaf");
        counts[state.outcome] += 1;
      }
    }

    visit(createGame(), 0);

