vm.runInContext(engine + '\n' + fs.readFileSync('tests/exhaustive.js', 'utf8'), validator);
console.log('Exhaustive validator:', JSON.stringify(vm.runInContext('KomiValidation.run()', validator)));
function setup(number) {
  const elements = [...html.matchAll(/<(button|div|p)\b([^>]*)>/g)].map(([, tag, attrs]) => {
    const attributes = Object.fromEntries([...attrs.matchAll(/([\w-]+)="([^"]*)"/g)].map(m => [m[1], m[2]]));
    return { tag, id: attributes.id, dataset: Object.fromEntries(Object.entries(attributes).filter(([k]) => k.startsWith('data-')).map(([k,v]) => [k.slice(5),v])), hidden: /\bhidden\b/.test(attrs), disabled: /\bdisabled\b/.test(attrs), textContent: '', handlers: {}, addEventListener(event, fn) { this.handlers[event] = fn; }, setAttribute(k,v) { attributes[k] = v; }, focus() {}, fire() { this.handlers.click(); } };
  });
  const cells = elements.filter(e => 'index' in e.dataset);
  assert(cells.every(e => e.disabled), 'Board disabled before JS loads');
  const guesses = elements.filter(e => 'guess' in e.dataset);
  const choices = elements.filter(e => 'mark' in e.dataset);
  const byId = id => elements.find(e => e.id === id);
  let randomCalls = 0;
  const math = Object.create(Math);
  math.random = () => { randomCalls++; return (number - 1 + 0.5) / 9; };
  const context = vm.createContext({Math: math, document: { getElementById: byId, querySelectorAll: s => s === '[data-guess]' ? guesses : s === '[data-mark]' ? choices : cells }});
  vm.runInContext(engine + '\n' + app, context);
  return {cells, guesses, choices, byId, calls: () => randomCalls};
}
let cases = 0;
for (let number = 1; number <= 9; number++) for (const guess of ['Odd', 'Even']) for (const mark of ['X', 'O']) for (const [moves, winnerMark, suffix] of [
  [[0,3,1,4,2], 'X', ''],
  [[0,3,1,4,8,5], 'O', ''],
  [[0,1,2,4,3,5,7,6,8], 'O', ' with Komi'],
]) {
  const {cells, guesses, choices, byId, calls} = setup(number);
  assert.equal(calls(), 0);
  cells[0].fire(); choices[0].fire();
  assert(cells.every(e => e.disabled && e.textContent === ''));
  guesses.find(e => e.dataset.guess === guess).fire();
  const chooser = (number % 2 === 0 ? 'Even' : 'Odd') === guess ? 1 : 2;
  assert(byId('status').textContent.startsWith(`Player ${chooser}, choose`));
  assert(byId('nigiri-result').textContent.includes(`Draw: ${number} (`));
  assert.equal(calls(), 1);
  cells[0].fire();
  assert(cells.every(e => e.disabled && e.textContent === ''));
  guesses[0].fire(); assert.equal(calls(), 1);
  choices.find(e => e.dataset.mark === mark).fire();
  const p1 = chooser === 1 ? mark : mark === 'X' ? 'O' : 'X';
  const human = m => m === p1 ? 1 : 2;
  const assignment = `Player 1 = ${p1} / Player 2 = ${p1 === 'X' ? 'O' : 'X'}`;
  assert.equal(byId('assignment').textContent, assignment);
  assert.equal(byId('status').textContent, `Player ${human('X')} (X)'s turn`);
  assert(cells.every(e => !e.disabled));
  choices[0].fire(); choices[1].fire();
  assert.equal(byId('assignment').textContent, assignment);
  assert(byId('mark-choices').hidden && byId('nigiri-guesses').hidden);
  moves.forEach((move, i) => {
    cells[move].fire();
    if (i < moves.length - 1) {
      const next = i % 2 === 0 ? 'O' : 'X';
      assert.equal(byId('status').textContent, `Player ${human(next)} (${next})'s turn`);
    }
  });
  assert.equal(byId('status').textContent, `Player ${human(winnerMark)} won${suffix}`);
  assert(cells.every(e => e.disabled));
  assert.equal(byId('play-again').hidden, false);
  byId('play-again').fire();
  assert(cells.every(e => e.disabled && e.textContent === ''));
  assert.equal(byId('assignment').textContent, '');
  assert.equal(byId('nigiri-result').textContent, '');
  assert.equal(byId('nigiri-guesses').hidden, false);
  assert(byId('mark-choices').hidden && byId('play-again').hidden);
  choices[0].fire(); cells[0].fire();
  assert(cells.every(e => e.disabled && e.textContent === ''));
  guesses[1].fire(); assert.equal(calls(), 2);
  assert(cells.every(e => e.disabled));
  cases++;
}
console.log(`UI flow checks passed: ${cases} scenarios (all draws 1-9, both guesses, both mark choices, all three outcomes, replay and input guards).`);
